data.diagramCode:
graph TD
    A[Start] --> B{Given function f(x)};
    B --> C[Calculate f(-x)];
    C --> D{Is f(-x) == f(x)?};
    D -- Yes --> E[f(x) is Even];
    D -- No --> F{Is f(-x) == -f(x)?};
    F -- Yes --> G[f(x) is Odd];
    F -- No --> H[f(x) is Neither Even nor Odd];
    E --> I[End];
    G --> I;
    H --> I;
